-- Celulares Samsung y Motorola (planilla COSTO CELULARES). Van después de los Xiaomi: se corre el resto para hacerles lugar.
update public.products set position = position + 32 where position >= 37 and id not in ('samsung-galaxy-a07', 'samsung-galaxy-a16', 'samsung-galaxy-a17', 'samsung-galaxy-a27-5g', 'samsung-galaxy-a37-5g', 'samsung-galaxy-a56-5g', 'samsung-galaxy-a57-5g', 'samsung-galaxy-s25', 'samsung-galaxy-s25-ultra', 'samsung-galaxy-s26', 'samsung-galaxy-s26-plus', 'samsung-galaxy-s26-ultra', 'motorola-edge-70-fusion', 'motorola-edge-70-fusion-fifa-edition', 'motorola-edge-70-pro', 'motorola-edge-70', 'moto-g-max', 'moto-g04s', 'moto-g05', 'moto-g06', 'moto-g15', 'moto-g17', 'moto-g17-power', 'moto-g56-5g', 'moto-g67', 'moto-g77', 'moto-g86-power', 'motorola-razr-60-ultra', 'motorola-razr-70', 'motorola-razr-70-ultra', 'motorola-razr-fold-fifa-edition', 'motorola-signature');
on conflict (id) do nothing;
